function HomepageFields({token,pageKey,data,load,notify,busy}) {
 const [draft,setDraft]=useState(data);useEffect(()=>setDraft(data),[data]);
 const keys=pageKey==="homepage/header"?["siteTitle","contactPhone","whatsappNumber","seoDescription"]:pageKey==="homepage/upcoming-festival"?["festivalTitle","festivalDescription","festivalDate"]:pageKey==="homepage/footer"?["footerDescription","contactPhone","whatsappNumber","seoDescription"]:pageKey==="homepage/search-section"?["searchSuggestionLimit"]:["seoDescription"];
 const labels={siteTitle:"Site title",contactPhone:"Contact phone",whatsappNumber:"WhatsApp number (digits only)",seoDescription:"SEO description",festivalTitle:"Festival title",festivalDescription:"Festival description",festivalDate:"Festival date",footerDescription:"Footer description",searchSuggestionLimit:"Maximum destination suggestions (1–10)"};
 const save=async()=>{try{await api("/admin/homepage",token,jsonBody(draft));notify("Homepage draft saved. Use Publish Homepage to make it live.");await load();}catch(e){notify(e.message);}};
 return <Panel title={titleFor(pageKey)} description="Edit the corresponding homepage content fields using the React editor."><div className="grid gap-4 sm:grid-cols-2">{keys.map(k=>k.toLowerCase().includes("description")? <div key={k} className="sm:col-span-2"><TextField label={labels[k]} value={draft[k]} onChange={v=>setDraft(s=>({...s,[k]:v}))} required/> </div>:<Field key={k} label={labels[k]} type={k==="searchSuggestionLimit"?"number":"text"} min={k==="searchSuggestionLimit"?1:undefined} max={k==="searchSuggestionLimit"?10:undefined} value={draft[k]} onChange={v=>setDraft(s=>({...s,[k]:k==="searchSuggestionLimit"?Number(v):v}))} required/>)}</div><div className="mt-5 flex flex-wrap gap-2"><button className={buttonClass} disabled={busy} onClick={save}>Save draft</button><button className={secondaryClass} disabled={busy} onClick={async()=>{if(!window.confirm("Publish the complete saved homepage draft?"))return;try{await api("/admin/homepage/publish",token,{method:"POST"});notify("Homepage published.");await load();}catch(e){notify(e.message);}}}>Publish homepage</button></div></Panel>;
}
